CREATE FUNCTION xep_hang(v int) RETURNS text
  LANGUAGE plpgsql IMMUTABLE
AS $$
BEGIN
  IF v >= 80 THEN RETURN 'viral';
  ELSIF v >= 40 THEN RETURN 'popular';
  ELSIF v > 0 THEN RETURN 'seen';
  ELSE RETURN 'unread';
  END IF;
END;
$$;

SELECT xep_hang(views) AS hang, count(*) AS notes
FROM notes
GROUP BY 1
ORDER BY 2 DESC, 1;

